blocks.code:
-- Courses that have at least one enrollment
SELECT title, topic
FROM courses
WHERE id IN (
  SELECT course_id FROM enrollments
);

-- DANGEROUS if enrollments.course_id can be NULL:
-- returns zero rows when any NULL sneaks into the list
SELECT title FROM courses
WHERE id NOT IN (SELECT course_id FROM enrollments);

-- SAFE: exclude NULLs from the list first
SELECT title FROM courses
WHERE id NOT IN (
  SELECT course_id FROM enrollments WHERE course_id IS NOT NULL
);

exercise.solution:
SELECT title FROM courses
WHERE id NOT IN (
  SELECT course_id FROM enrollments WHERE course_id IS NOT NULL
);

SELECT title FROM courses
WHERE NOT EXISTS (
  SELECT 1 FROM enrollments e WHERE e.course_id = courses.id
);

