-- Sandbox check (flat — runs here): the same absences via LEFT JOIN
SELECT c.title FROM courses c
LEFT JOIN enrollments e ON e.course_id = c.id
WHERE e.id IS NULL;

-- Full forms (real PostgreSQL / SQLite):
-- (a) NULL-safe NOT IN
SELECT title FROM courses
WHERE id NOT IN (
  SELECT course_id FROM enrollments WHERE course_id IS NOT NULL
);

-- (b) NULL-immune NOT EXISTS
SELECT title FROM courses
WHERE NOT EXISTS (
  SELECT 1 FROM enrollments e WHERE e.course_id = courses.id
);
